import java.io.File;
import java.util.EnumSet;

public class IconDetector extends Detector implements BinaryResourceScanner {
    public static final Issue ISSUE = Issue.create(
            "IconLocation",
            "Image defined in density-independent drawable folder",
            "The res/drawable folder is intended for density-independent graphics such as " +
            "shapes defined in XML. For bitmaps, move it to `drawable-mdpi` and consider " +
            "providing higher and lower resolution versions in `drawable-ldpi`, `drawable-hdpi` " +
            "and `drawable-xhdpi`. If the icon **really** is density independent (for example " +
            "a solid color) you can place it in `drawable-nodpi`.",
            Category.ICONS,
            5,
            Severity.WARNING,
            new Implementation(IconDetector.class, Scope.RESOURCE_FILE_SCOPE)
    );

    @Override
    public void checkBinaryResource(ResourceContext context) {
        File file = context.file;
        if (file == null) return;

        String name = file.getName();
        int dot = name.lastIndexOf('.');
        if (dot == -1) return;
        String ext = name.substring(dot + 1).toLowerCase();

        if (!isBitmapExtension(ext)) return;

        File parent = file.getParentFile();
        if (parent != null && "drawable".equals(parent.getName())) {
            context.report(ISSUE, Location.create(file), "Found bitmap drawable `res/drawable/" + name + "` in densityless folder");
        }
    }

    private static boolean isBitmapExtension(String ext) {
        return ext.equals("png") || ext.equals("jpg") || ext.equals("jpeg") ||
               ext.equals("gif") || ext.equals("bmp") || ext.equals("webp");
    }
}
```

